77	/// The single shared expert (a plain fp8 SwiGLU MLP at intermediate 2048).
78	/// gate|up are packed into one `[2*INTERMEDIATE, HIDDEN]` projection at build
79	/// so the decode path is one GEMV + SwiGLU + one GEMV.
80	pub(crate) struct Glm52MoeSharedExpert {
81	    gate_up: ProjWeight, // fp8 [2*INTERMEDIATE, HIDDEN] (gate | up)
82	    down: ProjWeight,    // fp8 [HIDDEN, INTERMEDIATE]
83	}
84	
85	impl Glm52MoeSharedExpert {
86	    pub(crate) fn new(
87	        ctx: &DeviceContext,
88	        gate: &ProjWeight,
89	        up: &ProjWeight,
90	        down: ProjWeight,
91	    ) -> Result<Self> {
92	        let shape = |label: &str, p: &ProjWeight, n: usize, k: usize| -> Result<()> {
93	            ensure!(
94	                p.n == n && p.k == k,
95	                "GLM5.2 MoE shared {label} shape [{},{}] != [{n},{k}]",
96	                p.n,
97	                p.k
98	            );
99	            Ok(())
100	        };
101	        shape("gate_proj", gate, INTERMEDIATE, HIDDEN)?;
102	        shape("up_proj", up, INTERMEDIATE, HIDDEN)?;
103	        shape("down_proj", &down, HIDDEN, INTERMEDIATE)?;
104	        Ok(Self {
105	            gate_up: pack_proj_pair(ctx, gate, up)?,
106	            down,
107	        })
108	    }
109	
110	    /// Shared-expert contribution into pre-allocated decode scratch.
111	    pub(crate) fn forward_into(
112	        &self,
113	        ctx: &DeviceContext,
114	        normed_hidden: &CudaSlice<bf16>,
115	        mlp: &mut Glm52MlpScratch,
116	        out: &mut CudaSlice<bf16>,
117	    ) -> Result<()> {
118	        fp8_mlp_into(ctx, &self.gate_up, &self.down, normed_hidden, mlp, out)
119	    }
120	}
