125	/// One EP rank's routed experts in the SM100 DeepGEMM layout.
126	pub(crate) struct Glm52MoeExpertBank {
127	    n_experts: usize,
128	    pub(crate) w13_weight: CudaSlice<u8>, // fp8  [n_experts, W13_N, W13_K]
129	    pub(crate) w13_scale: CudaSlice<i32>, // UE8M0 [n_experts, W13_K/512, W13_N]
130	    pub(crate) w2_weight: CudaSlice<u8>,  // fp8  [n_experts, W2_N, W2_K]
131	    pub(crate) w2_scale: CudaSlice<i32>,  // UE8M0 [n_experts, W2_K/512, W2_N]
132	}
133	
134	impl Glm52MoeExpertBank {
135	    fn new(
136	        ctx: &DeviceContext,
137	        n_experts: usize,
138	        mut w13_weight: CudaSlice<u8>,
139	        w13_scale_f32: CudaSlice<f32>,
140	        mut w2_weight: CudaSlice<u8>,
141	        w2_scale_f32: CudaSlice<f32>,
142	    ) -> Result<Self> {
143	        let check = |name: &str, have: usize, want: usize| -> Result<()> {
144	            ensure!(
145	                have == want,
146	                "GLM5.2 MoE expert bank {name} length {have} != expected {want}"
147	            );
148	            Ok(())
149	        };
150	        check("w13_weight", w13_weight.len(), n_experts * W13_N * W13_K)?;
151	        check(
152	            "w13_scale",
153	            w13_scale_f32.len(),
154	            n_experts * W13_SCALE_ROWS * HIDDEN_SCALE_COLS,
155	        )?;
156	        check("w2_weight", w2_weight.len(), n_experts * W2_N * W2_K)?;
157	        check(
158	            "w2_scale",
159	            w2_scale_f32.len(),
160	            n_experts * W2_SCALE_ROWS * W2_SCALE_COLS,
161	        )?;
162	        let mut w13_scale = ctx.stream.alloc_zeros(n_experts * (W13_K / 512) * W13_N)?;
163	        let mut w2_scale = ctx.stream.alloc_zeros(n_experts * (W2_K / 512) * W2_N)?;
164	        glm52_fp8_weight_ue8m0_prepare_launch(
165	            ctx,
166	            n_experts,
167	            W13_N,
168	            W13_K,
169	            &mut w13_weight,
170	            &w13_scale_f32,
171	            &mut w13_scale,
172	        )?;
173	        glm52_fp8_weight_ue8m0_prepare_launch(
174	            ctx,
175	            n_experts,
176	            W2_N,
177	            W2_K,
178	            &mut w2_weight,
179	            &w2_scale_f32,
180	            &mut w2_scale,
181	        )?;
182	        Ok(Self {
183	            n_experts,
184	            w13_weight,
185	            w13_scale,
186	            w2_weight,
187	            w2_scale,
188	        })
189	    }
190	
191	    /// Pack one rank's checkpoint experts for the multi-GPU oracle gates.
192	    #[cfg(test)]
193	    pub(crate) fn pack_from_host(
194	        ctx: &DeviceContext,
195	        experts: &[Glm52MoeRoutedExpertBytes<'_>],
196	    ) -> Result<Self> {
197	        let n_experts = experts.len();
198	        let mut w13_host: Vec<u8> = Vec::with_capacity(n_experts * W13_N * W13_K);
199	        let mut w13_scale_host: Vec<f32> =
200	            Vec::with_capacity(n_experts * W13_SCALE_ROWS * HIDDEN_SCALE_COLS);
201	        let mut w2_host: Vec<u8> = Vec::with_capacity(n_experts * W2_N * W2_K);
202	        let mut w2_scale_host: Vec<f32> =
203	            Vec::with_capacity(n_experts * W2_SCALE_ROWS * W2_SCALE_COLS);
204	        for (idx, expert) in experts.iter().enumerate() {
205	            let proj = |label: &str, p: &Glm52ProjBytes<'_>, n: usize, k: usize| -> Result<()> {
206	                ensure!(
207	                    p.n == n && p.k == k && p.weight.len() == n * k,
208	                    "GLM5.2 MoE expert {idx} {label} shape [{},{}] != [{n},{k}]",
209	                    p.n,
210	                    p.k
211	                );
212	                ensure!(
213	                    p.scale.len() == (n / QUANT_GROUP) * (k / QUANT_GROUP) * 4,
214	                    "GLM5.2 MoE expert {idx} {label} scale bytes {} unexpected",
215	                    p.scale.len()
216	                );
217	                Ok(())
218	            };
219	            proj("gate_proj", &expert.gate, INTERMEDIATE, HIDDEN)?;
220	            proj("up_proj", &expert.up, INTERMEDIATE, HIDDEN)?;
221	            proj("down_proj", &expert.down, HIDDEN, INTERMEDIATE)?;
222	            w13_host.extend_from_slice(expert.gate.weight);
223	            w13_host.extend_from_slice(expert.up.weight);
224	            w13_scale_host.extend_from_slice(&bytes_to_f32(expert.gate.scale));
225	            w13_scale_host.extend_from_slice(&bytes_to_f32(expert.up.scale));
226	            w2_host.extend_from_slice(expert.down.weight);
227	            w2_scale_host.extend_from_slice(&bytes_to_f32(expert.down.scale));
228	        }
229	        let stream = &ctx.stream;
230	        let upload_u8 = |host: &[u8]| -> Result<CudaSlice<u8>> {
231	            let mut dev = stream.alloc_zeros::<u8>(host.len())?;
232	            stream.memcpy_htod(host, &mut dev)?;
233	            Ok(dev)
234	        };
235	        let upload_f32 = |host: &[f32]| -> Result<CudaSlice<f32>> {
236	            let mut dev = stream.alloc_zeros::<f32>(host.len())?;
237	            stream.memcpy_htod(host, &mut dev)?;
238	            Ok(dev)
239	        };
240	        Self::new(
241	            ctx,
242	            n_experts,
243	            upload_u8(&w13_host)?,
244	            upload_f32(&w13_scale_host)?,
245	            upload_u8(&w2_host)?,
246	            upload_f32(&w2_scale_host)?,
247	        )
248	    }
249	
250	    /// Adopt one layer's loader-packed regions, then convert weights and
251	    /// scales to DeepGEMM's UE8M0 contract. The loader wrote the regions in
252	    /// exactly the `from_host` packing (proven by
253	    /// `expert_placement_matches_from_host_packing`); the expert count comes
254	    /// from the region size so bank and loader cannot drift.
255	    pub(crate) fn from_regions(
256	        ctx: &DeviceContext,
257	        regions: crate::weights::Glm52ExpertLayerRegions,
258	    ) -> Result<Self> {
259	        let stride = crate::weights::Glm52ExpertRegionKind::W13Weight.expert_stride();
260	        ensure!(
261	            regions.w13_weight.len().is_multiple_of(stride),
262	            "GLM5.2 expert region size {} is not a whole number of experts",
263	            regions.w13_weight.len()
264	        );
265	        let n_experts = regions.w13_weight.len() / stride;
266	        Self::new(
267	            ctx,
268	            n_experts,
269	            regions.w13_weight,
270	            crate::weights::retype_owned::<f32>(&ctx.stream, regions.w13_scale)?,
271	            regions.w2_weight,
272	            crate::weights::retype_owned::<f32>(&ctx.stream, regions.w2_scale)?,
273	        )
274	    }
275	
276	    pub(crate) fn n_experts(&self) -> usize {
277	        self.n_experts
278	    }
279	}
280	
281	/// Router output for one token: the top-8 GLOBAL expert ids and weights, both
282	/// device-resident (never read back to host). The caller chooses whether the
283	/// model's routed scale is folded into these weights.
284	pub(crate) struct RoutedTopk {
285	    pub(crate) topk_idx: CudaSlice<i32>,
286	    pub(crate) topk_weight: CudaSlice<f32>,
287	}
288	
289	/// Persistent router scratch for the decode path: the expert logits plus the
290	/// top-k output the MoE dispatch consumes, written in place every MoE layer.
291	/// Sized for `tokens` rows.
292	pub(crate) struct Glm52RouterScratch {
293	    tokens: usize,
294	    logits: CudaSlice<f32>,
295	    pub(crate) route: RoutedTopk,
296	}
297	
298	impl Glm52RouterScratch {
299	    pub(crate) fn new(ctx: &DeviceContext, tokens: usize) -> Result<Self> {
300	        ensure!(tokens > 0, "GLM5.2 router scratch needs positive tokens");
301	        // TP MoE keeps an eight-row ABI even when TP4's surrounding decode
302	        // graph uses a smaller bucket. Only `tokens` rows are launched; the
303	        // spare route capacity is padding storage for that fixed ABI.
304	        let capacity = tokens.max(GLM52_TP_TOKENS);
305	        Ok(Self {
306	            tokens,
307	            logits: ctx.stream.alloc_zeros::<f32>(capacity * EXPERTS)?,
308	            route: RoutedTopk {
309	                topk_idx: ctx.stream.alloc_zeros::<i32>(capacity * TOPK)?,
310	                topk_weight: ctx.stream.alloc_zeros::<f32>(capacity * TOPK)?,
311	            },
312	        })
313	    }
314	}
315	
316	pub(crate) fn run_ep_router_into(
317	    ctx: &DeviceContext,
318	    router: &Glm52MoeRouterWeights,
319	    normed_hidden: &CudaSlice<bf16>,
320	    s: &mut Glm52RouterScratch,
321	) -> Result<()> {
322	    run_router_into_with_config(
323	        ctx,
324	        router,
325	        normed_hidden,
326	        s,
327	        Glm52RouterConfig::glm52_unscaled(),
328	    )
329	}
330	
331	fn run_router_into_with_config(
332	    ctx: &DeviceContext,
333	    router: &Glm52MoeRouterWeights,
334	    normed_hidden: &CudaSlice<bf16>,
335	    s: &mut Glm52RouterScratch,
336	    config: Glm52RouterConfig,
337	) -> Result<()> {
338	    let mut router_out = Glm52RouterOutput {
339	        topk_weight: &mut s.route.topk_weight,
340	        topk_idx: &mut s.route.topk_idx,
341	    };
342	    glm52_router_noaux_tc_launch(
343	        ctx,
344	        config,
345	        Glm52RouterBatch {
346	            active_tokens: s.tokens,
347	            padded_tokens: s.tokens,
348	        },
349	        normed_hidden,
350	        &router.gate_weight,
351	        &router.e_score_bias,
352	        &mut s.logits,
353	        &mut router_out,
354	    )?;
355	    Ok(())
356	}
357	
358	pub(crate) fn run_router_rows_into(
359	    ctx: &DeviceContext,
360	    router: &Glm52MoeRouterWeights,
361	    normed_hidden: &CudaSlice<bf16>,
362	    active_tokens: usize,
363	    padded_tokens: usize,
364	    s: &mut Glm52RouterScratch,
365	) -> Result<()> {
366	    ensure!(
367	        active_tokens > 0
368	            && active_tokens <= padded_tokens
369	            && padded_tokens <= s.tokens
370	            && normed_hidden.len() >= padded_tokens * HIDDEN,
371	        "GLM5.2 router prefill shape is invalid"
372	    );
373	    gemm_bf16_f32(
374	        ctx,
375	        true,
376	        false,
377	        EXPERTS,
378	        padded_tokens,
379	        HIDDEN,
380	        &router.gate_weight,
381	        HIDDEN,
382	        normed_hidden,
383	        HIDDEN,
384	        &mut s.logits,
385	        EXPERTS,
386	    )?;
387	    let mut router_out = Glm52RouterOutput {
388	        topk_weight: &mut s.route.topk_weight,
389	        topk_idx: &mut s.route.topk_idx,
390	    };
391	    glm52_router_select_launch(
392	        ctx,
393	        Glm52RouterConfig::glm52(),
394	        Glm52RouterBatch {
395	            active_tokens,
396	            padded_tokens,
397	        },
398	        &s.logits,
399	        &router.e_score_bias,
400	        &mut router_out,
401	    )
402	}
403	
404	/// Allocating EP/unscaled router for oracle-gate/test paths.
405	#[cfg(test)]
406	pub(crate) fn run_ep_router(
407	    ctx: &DeviceContext,
408	    router: &Glm52MoeRouterWeights,
409	    normed_hidden: &CudaSlice<bf16>,
410	) -> Result<RoutedTopk> {
411	    let mut s = Glm52RouterScratch::new(ctx, 1)?;
412	    run_ep_router_into(ctx, router, normed_hidden, &mut s)?;
413	    Ok(s.route)
414	}
