259	        let stride = crate::weights::Glm52ExpertRegionKind::W13Weight.expert_stride();
260	        ensure!(
261	            regions.w13_weight.len().is_multiple_of(stride),
262	            "GLM5.2 expert region size {} is not a whole number of experts",
263	            regions.w13_weight.len()
264	        );
265	        let n_experts = regions.w13_weight.len() / stride;
266	        Self::new(
267	            ctx,
268	            n_experts,
269	            regions.w13_weight,
270	            crate::weights::retype_owned::<f32>(&ctx.stream, regions.w13_scale)?,
271	            regions.w2_weight,
272	            crate::weights::retype_owned::<f32>(&ctx.stream, regions.w2_scale)?,
273	        )
274	    }
275	
276	    pub(crate) fn n_experts(&self) -> usize {
277	        self.n_experts
278	    }
279	}
280	
281	/// Router output for one token: the top-8 GLOBAL expert ids and weights, both
282	/// device-resident (never read back to host). The caller chooses whether the
283	/// model's routed scale is folded into these weights.
284	pub(crate) struct RoutedTopk {
285	    pub(crate) topk_idx: CudaSlice<i32>,
286	    pub(crate) topk_weight: CudaSlice<f32>,
287	}
288	
289	/// Persistent router scratch for the decode path: the expert logits plus the
290	/// top-k output the MoE dispatch consumes, written in place every MoE layer.
291	/// Sized for `tokens` rows.
292	pub(crate) struct Glm52RouterScratch {
293	    tokens: usize,
294	    logits: CudaSlice<f32>,
295	    pub(crate) route: RoutedTopk,
296	}
297	
298	impl Glm52RouterScratch {
299	    pub(crate) fn new(ctx: &DeviceContext, tokens: usize) -> Result<Self> {
300	        ensure!(tokens > 0, "GLM5.2 router scratch needs positive tokens");
301	        // TP MoE keeps an eight-row ABI even when TP4's surrounding decode
302	        // graph uses a smaller bucket. Only `tokens` rows are launched; the
303	        // spare route capacity is padding storage for that fixed ABI.
304	        let capacity = tokens.max(GLM52_TP_TOKENS);
305	        Ok(Self {
306	            tokens,
307	            logits: ctx.stream.alloc_zeros::<f32>(capacity * EXPERTS)?,
308	            route: RoutedTopk {
309	                topk_idx: ctx.stream.alloc_zeros::<i32>(capacity * TOPK)?,
310	                topk_weight: ctx.stream.alloc_zeros::<f32>(capacity * TOPK)?,
311	            },
312	        })
313	    }
314	}
315	
316	pub(crate) fn run_ep_router_into(
317	    ctx: &DeviceContext,
318	    router: &Glm52MoeRouterWeights,
319	    normed_hidden: &CudaSlice<bf16>,
320	    s: &mut Glm52RouterScratch,
321	) -> Result<()> {
322	    run_router_into_with_config(
323	        ctx,
324	        router,
325	        normed_hidden,
326	        s,
327	        Glm52RouterConfig::glm52_unscaled(),
328	    )
329	}
330	
331	fn run_router_into_with_config(
332	    ctx: &DeviceContext,
333	    router: &Glm52MoeRouterWeights,
334	    normed_hidden: &CudaSlice<bf16>,
335	    s: &mut Glm52RouterScratch,
336	    config: Glm52RouterConfig,
337	) -> Result<()> {
338	    let mut router_out = Glm52RouterOutput {
339	        topk_weight: &mut s.route.topk_weight,
340	        topk_idx: &mut s.route.topk_idx,
341	    };
342	    glm52_router_noaux_tc_launch(
343	        ctx,
344	        config,
345	        Glm52RouterBatch {
346	            active_tokens: s.tokens,
347	            padded_tokens: s.tokens,
348	        },
349	        normed_hidden,
350	        &router.gate_weight,
351	        &router.e_score_bias,
352	        &mut s.logits,
353	        &mut router_out,
354	    )?;
355	    Ok(())
356	}
357	
358	pub(crate) fn run_router_rows_into(
359	    ctx: &DeviceContext,
360	    router: &Glm52MoeRouterWeights,
361	    normed_hidden: &CudaSlice<bf16>,
362	    active_tokens: usize,
363	    padded_tokens: usize,
364	    s: &mut Glm52RouterScratch,
365	) -> Result<()> {
366	    ensure!(
367	        active_tokens > 0
368	            && active_tokens <= padded_tokens
369	            && padded_tokens <= s.tokens
370	            && normed_hidden.len() >= padded_tokens * HIDDEN,
371	        "GLM5.2 router prefill shape is invalid"
372	    );
373	    gemm_bf16_f32(
374	        ctx,
375	        true,
376	        false,
377	        EXPERTS,
378	        padded_tokens,
379	        HIDDEN,
380	        &router.gate_weight,
381	        HIDDEN,
382	        normed_hidden,
383	        HIDDEN,
384	        &mut s.logits,
385	        EXPERTS,
386	    )?;
387	    let mut router_out = Glm52RouterOutput {
388	        topk_weight: &mut s.route.topk_weight,
389	        topk_idx: &mut s.route.topk_idx,
390	    };
391	    glm52_router_select_launch(
392	        ctx,
393	        Glm52RouterConfig::glm52(),
394	        Glm52RouterBatch {
395	            active_tokens,
396	            padded_tokens,
397	        },
398	        &s.logits,
399	        &router.e_score_bias,
400	        &mut router_out,
401	    )
402	}
403	
404	/// Allocating EP/unscaled router for oracle-gate/test paths.
405	#[cfg(test)]
406	pub(crate) fn run_ep_router(
407	    ctx: &DeviceContext,
408	    router: &Glm52MoeRouterWeights,
409	    normed_hidden: &CudaSlice<bf16>,
410	) -> Result<RoutedTopk> {
411	    let mut s = Glm52RouterScratch::new(ctx, 1)?;
412	    run_ep_router_into(ctx, router, normed_hidden, &mut s)?;
413	    Ok(s.route)
414	}
