104	fn validate_glm52_router_shapes(
105	    config: Glm52RouterConfig,
106	    batch: Glm52RouterBatch,
107	    hidden: &CudaSlice<bf16>,
108	    gate_weight: &CudaSlice<bf16>,
109	    e_score_correction_bias: &CudaSlice<u8>,
110	    logits: &CudaSlice<f32>,
111	    output: &Glm52RouterOutput<'_>,
112	) -> Result<()> {
113	    config.validate()?;
114	    batch.validate()?;
115	    let hidden_elems = batch.padded_tokens * config.hidden_dim;
116	    ensure!(
117	        hidden.len() >= hidden_elems,
118	        "GLM5.2 router hidden too small: have {}, need {}",
119	        hidden.len(),
120	        hidden_elems
121	    );
122	    let gate_elems = config.n_experts * config.hidden_dim;
123	    ensure!(
124	        gate_weight.len() >= gate_elems,
125	        "GLM5.2 router gate_weight too small: have {}, need {gate_elems}",
126	        gate_weight.len()
127	    );
128	    let bias_bytes = config.n_experts * std::mem::size_of::<f32>();
129	    ensure!(
130	        e_score_correction_bias.len() >= bias_bytes,
131	        "GLM5.2 router correction bias too small: have {} bytes, need {bias_bytes}",
132	        e_score_correction_bias.len()
133	    );
134	    let score_elems = batch.padded_tokens * config.n_experts;
