1	//! GLM5.2 routed-MoE decode: the DeepEP dispatch/combine collectives around
2	//! SM100 DeepGEMM masked grouped GEMMs, generic over
3	//! the shim instantiation (EP4 = 4 ranks × 64 local experts, EP8 = 8 × 32 —
4	//! every shape below comes from the shim's `DeepEpInfo`, so a new EP width
5	//! is a new instantiation, not new code).
6	//!
7	//! Every rank enters the collective per MoE layer with the protocol-max
8	//! `global_tokens`; the expert GEMMs consume the DeepEP aligned receive
9	//! layout through a compact masked-layout bridge:
10	//!
11	//! ```text
12	//! dispatch(x bf16, global topk)        # collective; recv = expert-major
13	//!   → psum → masked row metadata
14	//!   → UE8M0 fp8 quant → DeepGEMM W13
15	//!   → silu(gate)·up + UE8M0 fp8 quant → DeepGEMM W2
16	//!   → route_weight + remap to aligned slots
17	//!   → combine                          # collective; sums slots per token
18	//! ```
19	//!
20	//! All buffers are fixed at startup and every launch is host-quiet, preserving
21	//! whole-step CUDA Graph capture. Metadata traps on a cross-rank token-count
22	//! disagreement or a per-expert row count beyond the protocol maximum.
23	
24	use std::mem::size_of;
25	
26	use anyhow::Context as _;
27	use anyhow::Result;
28	use anyhow::ensure;
29	use cudarc::driver::CudaSlice;
30	use half::bf16;
31	use pegainfer_kernels::ffi::DeepEpInfo;
32	use pegainfer_kernels::ops::DeepEpAbi;
33	use pegainfer_kernels::ops::DeepEpBase;
34	use pegainfer_kernels::ops::DeepEpDispatchScratch;
35	use pegainfer_kernels::ops::GLM52_DEEPGEMM_GROUPED_EXPERT_ALIGNMENT;
36	use pegainfer_kernels::ops::GLM52_DEEPGEMM_SM100_MASKED_ALIGNMENT;
37	use pegainfer_kernels::ops::Glm52DeepEpAbi;
38	use pegainfer_kernels::ops::Glm52DeepGemmGroupedFp8Kind;
39	use pegainfer_kernels::ops::Glm52Ep4DeepEpAbi;
40	use pegainfer_kernels::ops::Glm52Ep16DeepEpAbi;
41	use pegainfer_kernels::ops::Glm52Ep32DeepEpAbi;
42	use pegainfer_kernels::ops::Glm52Ep64DeepEpAbi;
43	use pegainfer_kernels::ops::Glm52MoeQuantShape;
44	use pegainfer_kernels::ops::glm52_deepgemm_sm100_grouped_fp8_metadata_launch;
45	use pegainfer_kernels::ops::glm52_deepgemm_sm100_masked_grouped_fp8_launch;
46	use pegainfer_kernels::ops::glm52_deepgemm_sm100_masked_out_to_aligned_launch;
47	use pegainfer_kernels::ops::glm52_fp8_per_token_group_quant_bf16_masked_launch;
