    glm52_final_norm_into(ctx, &s.hidden, final_norm, &mut s.final_normed)?;
    glm52_lm_head_into(ctx, &s.final_normed, lm_head, &mut s.logits)?;
    // Device greedy argmax per row (same semantics as a host scan: lowest
    // index wins ties, NaN never wins) — the step's egress shrinks from the
    // full vocab rows to 6 bytes per row, and the kernel chain ends on-device
    // (the graph boundary). Two-stage: per-4096-tile partials in parallel,
    // then one finalize block per row — bit-identical to the single-block
    // scan (the partials carry global indices, same total order), and each
    // row's result is independent of its slot-mates.
    argmax_bf16_split_into(
        ctx,
        s.logits.data(),
        batch,
        lm_head.rows,
        &mut s.argmax_partial_values,
        &mut s.argmax_partial_indices,
        &mut s.argmax_values,
        &mut s.argmax_indices,
    )?;

    if tp.is_some() {
        anyhow::bail!("GLM5.2 TP4 is prefill-only; decode vocab-parallel LL allreduce was removed");
    }
    ensure!(
        lm_head.rows == GLM52_VOCAB && vocab_start == 0,
        "GLM5.2 non-TP decode received a sharded vocabulary head"
    );
    Ok(())
}

/// One layer's EP MoE half (EP8 or EP4 — the state carries the chain):
/// shared expert forked to the aux stream, routed path through router +
/// DeepEP dispatch/expert-GEMM/combine, joined by the closing add into
/// `mlp_out`. The events recorded here during capture become graph edges;
/// replay keeps the parallel branches.
pub(super) fn glm52_moe_ep_layer(
    ctx: &DeviceContext,
    aux: &DeviceContext,
    ep8: &mut Glm52MoeEpState,
    moe: &Glm52MoeEp8LayerWeights,
    s: &mut Glm52DecodeScratch,
    batch: usize,
    global_tokens: usize,
) -> Result<()> {
    // Fork: the shared expert only needs `normed2`, so it runs on the aux
    // stream concurrently with the routed path's dispatch/grouped-GEMM/
    // combine — the cooperative collectives occupy a fixed SM slice and
    // mostly wait on peers, leaving the rest of the GPU free.
    let normed_ready = ctx.stream.record_event(None)?;
    aux.stream.wait(&normed_ready)?;
    moe.shared.forward_into(
        aux,
        s.layer.normed2.data(),
        &mut s.shared_mlp,
        s.layer.shared_out.data_mut(),
    )?;
    let shared_done = aux.stream.record_event(None)?;

    run_ep_router_into(ctx, &moe.router, s.layer.normed2.data(), &mut s.router)?;
    let dispatched = ep8.routed_forward(
        ctx,
        &moe.bank,
        Some((s.layer.normed2.data(), &s.router.route, batch)),
        global_tokens,
    )?;
    ensure!(
        dispatched,
        "EP MoE returned no combined output for the dispatched rows"
    );
    // Join: the closing add consumes both branches.
    ctx.stream.wait(&shared_done)?;
    add_scaled_bf16_into(
        ctx,
        ep8.combined(),
        crate::config::GLM52_ROUTED_SCALING_FACTOR as f32,
        s.layer.shared_out.data(),
        batch * GLM52_HIDDEN,
        s.layer.mlp_out.data_mut(),
    )
}

//! Safe wrapper over the DeepEP elastic shim (csrc/deepep/).
//!
//! The shim is instantiated once per baked model config (Kimi-K2 `deepep_*`
//! symbols, GLM5.2 `glm52_deepep_*`); [`DeepEpAbi`] maps one instantiation's C
//! table into the shared wrapper [`DeepEpBase`]. One context per rank, used
//! from that rank's worker thread. All kernel launches are stream-ordered on
//! the caller's [`DeviceContext`] stream; the decode path has fixed worst-case
//! shapes and is CUDA-graph capturable.
//!
//! Layout contract (expanded mode): `recv.x` rows are per-(expert, token)
//! slots; each local expert's segment is contiguous and aligned to
//! [`DeepEpInfo::expert_alignment`]; `psum_expert` holds the running aligned
//! offsets (exclusive form). Combine never applies router weights — the
//! caller weights expert outputs before `decode_combine`.

use std::ffi::CStr;
use std::ffi::c_char;
use std::ffi::c_int;
use std::ffi::c_void;
use std::ptr::NonNull;

use anyhow::Result;
use anyhow::anyhow;
use anyhow::ensure;
use cudarc::driver::CudaSlice;
use cudarc::driver::DevicePtr;
use cudarc::driver::DevicePtrMut;
use half::bf16;

use crate::ffi::DeepEpInfo;
use crate::ffi::{self};
use crate::tensor::DeviceContext;

/// The C table of one shim instantiation. Every method forwards to the
/// matching `<prefix>_deepep_*` symbol; see csrc/deepep/deepep.h for the
/// contract.
#[allow(clippy::missing_safety_doc, clippy::too_many_arguments)]
pub trait DeepEpAbi {
    type RawCtx;

    unsafe fn last_error() -> *const c_char;
    fn info() -> DeepEpInfo;
    unsafe fn unique_id(out: *mut u8) -> c_int;
    unsafe fn ctx_create(
        unique_id: *const u8,
        num_ranks: i32,
        rank_idx: i32,
        out: *mut *mut Self::RawCtx,
    ) -> c_int;
    unsafe fn ctx_destroy(ctx: *mut Self::RawCtx) -> c_int;
    unsafe fn decode_dispatch(
        ctx: *mut Self::RawCtx,
        stream: *mut c_void,
        x: *const c_void,
        topk_idx: *const i32,
        topk_weights: *const f32,
        num_tokens: i32,
        rank_count_scratch: *mut i32,
        dst_slot_scratch: *mut i32,
        psum_rank: *mut i32,
        psum_expert: *mut i32,
        recv_x: *mut c_void,
        recv_topk_weights: *mut f32,
        recv_src_metadata: *mut i32,
    ) -> c_int;
    unsafe fn decode_combine(
        ctx: *mut Self::RawCtx,
        stream: *mut c_void,
        x: *const c_void,
        src_metadata: *const i32,
        psum_rank: *const i32,
        combined_topk_idx: *const i32,
        num_tokens: i32,
        combined_x: *mut c_void,
    ) -> c_int;
}

/// Optional CPU-synchronized prefill capability. GLM5.2 deliberately does
/// not implement this trait: its scheduler sends prompt rows through decode.
#[allow(clippy::missing_safety_doc, clippy::too_many_arguments)]
